import cmath
coef = [1, -3, 4, -2]
def p(x):
    v = 0
    for c in coef:
        v = v*x + c
    return v
roots = [(0.4+0.9j)**k for k in range(3)]
for _ in range(500):
    new = []
    for i, ri in enumerate(roots):
        den = 1
        for j, rj in enumerate(roots):
            if i != j:
                den *= (ri - rj)
        new.append(ri - p(ri)/den)
    roots = new
real = [t for t in roots if abs(t.imag) < 1e-9]
assert len(real) == 1
print(round(real[0].real))

