def mul(a, b):
    return (a[0]*b[0] - a[1]*b[1], a[0]*b[1] + a[1]*b[0])
def pw(z, n):
    r = (1, 0)
    while n:
        if n & 1:
            r = mul(r, z)
        z = mul(z, z)
        n >>= 1
    return r
x, y = pw((1, 1), 2024)
assert y == 0 and x == 2**1012
print("2^{1012}")

